using Microsoft.Xna.Framework;
namespace StarlightSyndicateDemo;
internal static class ShipBatch21Tests
{
 public static void Run(){int checks=0;void Check(bool value,string label){if(!value)throw new Exception("BATCH21 FAIL: "+label);checks++;}
 Check(ShipBatch21.Previous.Length==82&&FleetCatalog.Playable.Length==400,"exact batch scope");
 var world=new DemoWorld();world.NewGame(0);world.Credits=1000000;
 foreach(var profile in ShipBatch21.Previous){var hull=FleetCatalog.ById[profile.ShipId];world.Screen=ViewMode.Station;world.Grid="station";world.SystemId=profile.HomeSystem;float before=world.Credits;
 Check(world.BoardFleetHull(hull.Id),"acquire "+hull.Name);var ship=world.Player;Check(world.Credits==before-(profile.Starter||profile.LegacyCharter?0:(float)profile.Price),"exact acquisition price "+hull.Name);
 Check(hull.Attributes.Where(a=>ShipAttributeCatalog.ByKey.ContainsKey(a.Key)&&a.Key is not ("cpuLoad" or "powerLoad")).All(a=>Math.Abs((ship.Attributes.GetValueOrDefault(a.Key)??0)-a.Value)<.001),"source attributes unmodified "+hull.Name+" / "+string.Join(",",hull.Attributes.Where(a=>ShipAttributeCatalog.ByKey.ContainsKey(a.Key)&&a.Key is not ("cpuLoad" or "powerLoad")&&Math.Abs((ship.Attributes.GetValueOrDefault(a.Key)??0)-a.Value)>.001).Select(a=>a.Key+":"+a.Value+"/"+ship.Attributes.GetValueOrDefault(a.Key))));
 Check(world.TotalFitCpu<=ship.Stat("cpuOutput")+.001&&world.TotalFitPower<=ship.Stat("powerOutput")+.001,"legal budget "+hull.Name);
 foreach(string slot in new[]{"high","medium","low"})Check(FittingLayoutModel.Installed(ship).Count(m=>m.Bank==slot)<=ship.Stat(slot=="high"?"hiSlots":slot=="medium"?"medSlots":"lowSlots"),"shared sockets "+hull.Name+" "+slot);
 Check(world.CargoUsed<=ship.CargoMax+.001,"real spare cargo "+hull.Name);Check(ship.TotalDps>0&&double.IsFinite(ship.EffectiveHitpoints),"finite offensive and defensive stats "+hull.Name);
 Check(ship.Drones.Sum(d=>d.Definition.Volume)<=ship.Stat("droneCapacity")&&ship.Drones.Sum(d=>d.Definition.Bandwidth)<=ship.Stat("droneBandwidth"),"bay and bandwidth "+hull.Name);
 if(profile.Starter)Check(ship.Utilities.Any(s=>s.Definition?.Harvest==true),"starter mining "+hull.Name);
 if(profile.Role=="Exploration")Check(ship.Utilities.Any(s=>s.Definition?.Kind=="CoreProbe")&&ship.Utilities.Any(s=>s.Definition?.Kind=="Data")&&ship.Utilities.Any(s=>s.Definition?.Kind=="Relic"),"exploration mission equipment "+hull.Name);
 if(profile.Role=="Logistics")Check(ship.Support.Any(s=>s.Definition?.Repair==true),"remote repair "+hull.Name);
 if(profile.Role=="Electronic warfare")Check(ship.Ewar.Any(s=>s.Definition!=null),"EW mission equipment "+hull.Name);
 world.EnterGrid("belt");var target=world.Targets.First(t=>t.Kind==TargetKind.Raider);target.Position=ship.Position+new Vector3(1200,0,0);target.Velocity=Vector3.Zero;target.Profile!.SetStat("shieldCapacity",100000);target.Profile.SetStat("armorHP",100000);target.Profile.SetStat("hp",100000);target.Shield=target.Armor=target.Hull=100000;world.SelectedId=world.LockedId=target.Id;world.ToggleFleetRack();for(int i=0;i<180;i++)world.Update(1f/30);Check(target.Shield+target.Armor+target.Hull<300000,"live weapon damage "+hull.Name);
 Console.WriteLine("BATCH21 PASS: "+hull.Name+" / "+profile.Role);
 }
 world.Screen=ViewMode.Station;world.Grid="station";var active=world.Player;var cash=world.Credits;var count=world.FleetBerths.Count;
 var paid=ShipBatch21.All.First(h=>!h.Starter&&!h.LegacyCharter);var reject=new DemoWorld();reject.NewGame(0);reject.Credits=0;reject.SystemId=paid.HomeSystem;Check(!reject.BoardFleetHull(paid.ShipId)&&reject.FleetBerths.Count==0&&reject.Credits==0,"insufficient funds atomic");reject.Credits=10000;reject.SystemId=paid.HomeSystem=="aster"?"vale":"aster";Check(!reject.BoardFleetHull(paid.ShipId)&&reject.Credits==10000,"wrong station atomic");
 // Numerical reference cases at proficiency I and V, independent of authored fits.
 var punisher=new Ship();punisher.ApplyFleetHull(FleetCatalog.Source("Punisher"));var skill=ShipBatch21.ById[punisher.CombatHull].Traits.First(t=>t.Skill!=0).Skill;punisher.HullProficiency[skill]=5;Check(Math.Abs(punisher.Stat("armorEmDamageResonance")-FleetCatalog.Source("Punisher").Value("armorEmDamageResonance")*.8)<.0001,"4 percent armor resistance per level");
 var kestrel=new Ship();kestrel.ApplyFleetHull(FleetCatalog.Source("Kestrel"));var missile=WeaponCatalog.All.First(w=>w.Family=="Missile Launcher Light"&&w.Size==1);Check(Math.Abs(kestrel.HullWeapon(missile,"damage","Kinetic")-1.05)<.001&&Math.Abs(kestrel.HullWeapon(missile,"damage","Explosive")-1.05)<.001,"Kestrel all damage bonus");
 var exploration=new Ship();exploration.ApplyFleetHull(FleetCatalog.Source("Heron"));Check(exploration.Stat("virusStrengthBonus")==5&&Math.Abs(exploration.UtilityFactor("probeStrength")-1.075)<.001,"scan and hacking bonuses");

 Ship Hull(string name,int level=1){var h=new Ship();h.ApplyFleetHull(FleetCatalog.Source(name));foreach(int skill in ShipBatch21.ById[h.CombatHull].Traits.Where(t=>t.Skill!=0).Select(t=>t.Skill).Distinct())h.HullProficiency[skill]=level;return h;}
 bool Near(double a,double b)=>Math.Abs(a-b)<.0001;
 var rail=WeaponCatalog.All.First(w=>w.Size==1&&w.Family=="Railguns");var laser=WeaponCatalog.All.First(w=>w.Size==1&&w.Family=="Pulse lasers");var rocket=WeaponCatalog.All.First(w=>w.Size==1&&w.Family=="Missile Launcher Rocket");
 Check(Near(Hull("Cormorant",5).WeaponProjection(rail,"optimal"),2.25),"Cormorant role range plus per-level range");
 Check(Near(Hull("Tristan",5).WeaponProjection(rail,"tracking"),1.375),"Tristan tracking at proficiency V");
 Check(Near(Hull("Punisher",5).RigWeapon(laser,"cap"),.5),"laser capacitor reduction");
 Check(Near(Hull("Rifter",5).WeaponEnhancement(WeaponCatalog.All.First(w=>w.Size==1&&w.Family=="Autocannons"),"cycle"),.625),"projectile ROF reduces cycle");
 var talwar=Hull("Talwar",5);Check(Near(talwar.HullWeapon(missile,"damage","Explosive"),1.25)&&Near(talwar.HullWeapon(missile,"damage","Kinetic"),1),"typed explosive missile bonus");
 Check(Near(Hull("Vigil Fleet Issue",5).HullWeapon(rocket,"damage","Explosive"),2.25)&&Near(Hull("Vigil Fleet Issue",5).HullWeapon(rocket,"damage","EM"),2),"typed rocket bonuses");
 var armorRemote=SupportCatalog.All.First(d=>d.Size==1&&d.Kind=="Armor");var shieldRemote=SupportCatalog.All.First(d=>d.Size==1&&d.Kind=="Shield");var nav=Hull("Navitas",5).HullSupport(armorRemote)!;var bantam=Hull("Bantam",5).HullSupport(shieldRemote)!;
 Check(Near(nav.Amount/armorRemote.Amount,1.5)&&Near(nav.Capacitor/armorRemote.Capacitor,.5)&&Near(nav.Optimal/armorRemote.Optimal,1.5)&&Near(nav.Falloff/armorRemote.Falloff,7),"Navitas remote repair amount, cap and role range");
 Check(Near(bantam.Amount/shieldRemote.Amount,1.5)&&Near(bantam.Capacitor/shieldRemote.Capacitor,.5)&&Near(bantam.Falloff/shieldRemote.Falloff,4),"Bantam shield logistics");
 var damp=EwarCatalog.All.First(d=>d.Kind==EwarKind.Damp);var jammer=EwarCatalog.All.First(d=>d.Kind==EwarKind.ECM);var disrupt=EwarCatalog.All.First(d=>d.Kind==EwarKind.Tracking);
 Check(Near(Hull("Maulus",5).HullEwar(damp)!.Strength/damp.Strength,1.375)&&Near(Hull("Maulus",5).HullEwar(damp)!.Capacitor/damp.Capacitor,.5),"damp strength and capacitor");
 Check(Near(Hull("Griffin",5).HullEwar(jammer)!.Strength/jammer.Strength,1.75),"sensor matched ECM hull strength");
 var navy=Hull("Crucifier Navy Issue",5);Check(Near(navy.HullEwar(disrupt)!.Optimal/disrupt.Optimal,.15)&&Near(navy.HullEwar(disrupt)!.Capacitor/disrupt.Capacitor,.15)&&Near(navy.RigCpu(disrupt.Id,disrupt.Cpu)/disrupt.Cpu,.15),"navy disruptor range penalty, cap and CPU reduction");
 var drone=DroneCatalog.All.First(d=>!d.Fighter&&d.Kind=="Combat");var enhanced=drone.Enhanced(Hull("Algos",5));Check(Near(enhanced.Packet.Total/drone.Packet.Total,1.5)&&Near(enhanced.Shield/drone.Shield,1.5)&&Near(enhanced.Speed/drone.Speed,1.25),"Algos live drone damage, health and role speed");
 Check(Near(Hull("Heron",5).UtilityFactor("probeStrength"),1.375)&&Hull("Heron",5).Stat("virusStrengthBonus")==5,"exploration proficiency and single application of flat hacking bonus");
 Check(Near(talwar.HullFactor("prop","signature","MWD"),.25),"MWD penalty reduction at V");
 Check(Near(Hull("Coercer Navy Issue",5).MaxArmor/FleetCatalog.Source("Coercer Navy Issue").Value("armorHP"),1.375),"navy armor HP multiplier");
 // Remote repair reaches an ally and consumes the reduced capacitor cost in the live loop.
 var medic=new DemoWorld();medic.NewGame(0);medic.Credits=10000;medic.SystemId=ShipBatch21.ById[FleetCatalog.Source("Navitas").Id].HomeSystem;Check(medic.BoardFleetHull(FleetCatalog.Source("Navitas").Id),"acquire logistics fixture");medic.EnterGrid("belt");var ally=medic.Targets.First(t=>t.Kind==TargetKind.Raider);ally.Friendly=true;ally.Position=medic.Player.Position+new Vector3(1000,0,0);ally.Armor=1;medic.LockedId=medic.SelectedId=ally.Id;Check(medic.ToggleSupport(0),"activate real remote armor repair");for(int i=0;i<400;i++)medic.UpdateSupport(.05f);Check(ally.Armor>1,"remote repair lands in live simulation");
 var ew=new DemoWorld();ew.NewGame(0);ew.Credits=10000;ew.SystemId="aster";Check(ew.BoardFleetHull(FleetCatalog.Source("Maulus").Id),"acquire EWAR fixture");ew.EnterGrid("belt");var victim=ew.Targets.First(t=>t.Kind==TargetKind.Raider);victim.Position=ew.Player.Position+new Vector3(1000,0,0);ew.LockedId=ew.SelectedId=victim.Id;ew.ToggleEwar(1);ew.Update(.1f);Check(ew.EwarFor(victim.Id).LockRange<1,"damp changes actual target sensors");
 var training=new DemoWorld();training.NewGame(0);training.BoardFleetHull(FleetCatalog.Source("Punisher").Id);training.Credits=10000;int trainingSkill=ShipBatch21.ById[training.Player.CombatHull].Traits.First(t=>t.Skill!=0).Skill;training.Player.Armor*=.4f;float fraction=training.Player.Armor/training.Player.MaxArmor;Check(training.TrainHullProficiency(trainingSkill)&&training.Player.HullProficiency[trainingSkill]==2&&Near(training.Player.Armor/training.Player.MaxArmor,fraction),"training pays and preserves damage fraction");
 var purchase=new DemoWorld();purchase.NewGame(0);purchase.SystemId=paid.HomeSystem;purchase.Credits=10000;var campaign=purchase.Player;Check(purchase.BuyAdditionalFleetHull(paid.ShipId)&&ReferenceEquals(campaign,purchase.Player)&&purchase.FleetBerths.Count==1&&purchase.Credits==10000-(float)paid.Price,"additional purchase preserves active ship and exact wallet");Check(purchase.BoardFleetBerth(0)&&purchase.Player.CombatHull==paid.ShipId,"board additional fitted hull");
 string temp=Path.Combine(Path.GetTempPath(),"batch21-"+Guid.NewGuid());var old=Environment.GetEnvironmentVariable("STARLIGHT_SAVE_DIR");try{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",temp);world.Save();var loaded=new DemoWorld();bool loadedOk=loaded.Load();Check(loadedOk&&loaded.FleetBerths.Count==world.FleetBerths.Count&&loaded.GrantedFleetHulls.Count==82,"82 acquired hulls save and load / "+string.Join(";",world.Log.TakeLast(2))+" / "+string.Join(";",loaded.Log.Take(2))+" / "+loaded.FleetBerths.Count+" / "+loaded.GrantedFleetHulls.Count);Check(loaded.Player.CombatHull==world.Player.CombatHull,"active hull persisted");foreach(var berth in world.FleetBerths){var copy=loaded.FleetBerths.First(b=>b.System==berth.System&&b.Ship.CombatHull==berth.Ship.CombatHull);Check(copy.Ship.Attributes.SequenceEqual(berth.Ship.Attributes),"exact parked attributes persisted "+berth.Ship.HullName);}}finally{Environment.SetEnvironmentVariable("STARLIGHT_SAVE_DIR",old);if(Directory.Exists(temp))Directory.Delete(temp,true);}
 Console.WriteLine(checks+" batch21 checks passed / all 82 hulls.");
 }
}
